// Classify input type and prepare for intent detection
const input = $input.first().json.body;
const text = input.text || input.message || '';
const hasImage = !!input.image_url || !!input.media_path;
const hasVoice = !!input.voice_url;
const userId = input.user_id || 'anonymous';
const traceId = Math.random().toString(16).slice(2, 14);
const startTime = Date.now();

let inputType = 'text_only';
if (hasImage) inputType = 'has_image';
if (hasVoice) inputType = 'voice';

return [{
  json: {
    text,
    inputType,
    userId,
    traceId,
    startTime,
    hasImage,
    hasVoice,
    imageUrl: input.image_url || null,
    voiceUrl: input.voice_url || null
  }
}];

// Extract intent and build the appropriate prompt
const llmResult = $input.first().json;
const meta = $('Classify Input Type').first().json;
const rawIntent = llmResult.choices[0].message.content.trim().toLowerCase();

// Normalize intent
let intent = 'general';
if (rawIntent.includes('fault')) intent = 'fault';
else if (rawIntent.includes('maintenance')) intent = 'maintenance';
else if (rawIntent.includes('status')) intent = 'status';

const prompts = {
  fault: `You are FactoryLM, an expert industrial fault diagnosis AI. Analyze the reported fault condition. Identify likely root causes, severity (critical/warning/info), and provide step-by-step troubleshooting instructions.\n\nError codes: 0=None, 1=Motor overload, 2=Temp high, 3=Conveyor jam, 4=Sensor failure, 5=Comm loss\n\nTechnician report: ${meta.text}`,
  maintenance: `You are FactoryLM, a preventive maintenance advisor. Based on the question, provide a maintenance checklist with: inspection items, recommended intervals, tools needed, and safety precautions.\n\nTechnician question: ${meta.text}`,
  status: `You are FactoryLM, a factory systems monitor. Provide a concise status overview. Normal ranges: Temp 20-60C, Current 0-5A, Pressure 80-120 PSI, Speed 0-100%.\n\nOperator question: ${meta.text}`,
  general: `You are FactoryLM, an industrial automation assistant. Be concise, practical, and helpful.\n\nTechnician question: ${meta.text}`
};

return [{
  json: {
    intent,
    model: 'groq-main',
    messages: [
      { role: 'system', content: prompts[intent] },
      { role: 'user', content: meta.text }
    ],
    temperature: 0.3,
    max_tokens: 1024,
    _meta: { trace_id: meta.traceId, user_id: meta.userId, start_time: meta.startTime, intent, input_type: meta.inputType }
  }
}];

// Extract final response
const llmResponse = $input.first().json;
const meta = $('Route by Intent').first().json._meta;
const elapsed = (Date.now() - meta.start_time) / 1000;

return [{
  json: {
    text: llmResponse.choices[0].message.content,
    trace_id: meta.trace_id,
    user_id: meta.user_id,
    intent: meta.intent,
    input_type: meta.input_type,
    provider: llmResponse.model || 'groq-main',
    elapsed_s: Math.round(elapsed * 10) / 10
  }
}];
